from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path


def _tail(path: Path, limit: int = 5000) -> list[str]:
    if not path.exists():
        return []
    try:
        with path.open("r", encoding="utf-8") as f:
            return f.readlines()[-limit:]
    except OSError:
        return []


def candle_history(data_root: str | Path, instrument_id: str, limit: int = 80) -> list[dict]:
    path = Path(data_root) / "candles" / f"{datetime.now(timezone.utc):%Y-%m-%d}.jsonl"
    rows = []
    for line in _tail(path):
        try:
            row = json.loads(line)
        except json.JSONDecodeError:
            continue
        if str(row.get("instrument_id")) == str(instrument_id) and row.get("complete") and int(row.get("timeframe_seconds", 0)) == 300:
            rows.append(row)
    return rows[-limit:]


